def build(rows: list, difficulty: str, start_id: int) -> list[dict]:
    out = []
    for i, (q, choices, ans, expl, tags) in enumerate(rows, start=start_id):
        out.append({
            "id": i,
            "subtest": B["subtest"],
            "module": B["module"],
            "subtopic": B["subtopic"],
            "difficulty": difficulty,
            "question": q,
            "choices": choices,
            "answer": ans,
            "explanation": expl,
            "tags": tags,
            "category": B["category"],
            "language": B["language"],
        })
    return out


def main() -> None:
    from pathlib import Path

    counts = f"EASY={len(EASY)} MEDIUM={len(MEDIUM)} HARD={len(HARD)}"
    print(counts)

    # Write counts to file for verification
    Path("_gen_counts.txt").write_text(counts, encoding="utf-8")

    if len(EASY) != 200 or len(MEDIUM) != 200 or len(HARD) != 200:
        print(f"ERROR: Counts don't match 200/200/200")
        return

    questions = []
    questions.extend(build(EASY, "Easy", 1))
    questions.extend(build(MEDIUM, "Medium", 201))
    questions.extend(build(HARD, "Hard", 401))

    assert len(questions) == 600, f"Expected 600 total, got {len(questions)}"

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(questions, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Wrote {len(questions)} questions to {OUTPUT}")


if __name__ == "__main__":
    main()
